def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    chars = list(dict.fromkeys(alphabet))
    K = len(chars)
    index = {c: i for i, c in enumerate(chars)}
    adj = [[-1] * K]
    term = [False]

    def add_node() -> int:
        adj.append([-1] * K)
        term.append(False)
        return len(adj) - 1

    for word in banned:
        v = 0
        for ch in word:
            ci = index[ch]
            if adj[v][ci] == -1:
                adj[v][ci] = add_node()
            v = adj[v][ci]
        if word:
            term[v] = True

    m = len(adj)
    fail = [0] * m
    go = [[0] * K for _ in range(m)]
    from collections import deque
    q = deque()
    for c in range(K):
        u = adj[0][c]
        if u != -1:
            go[0][c] = u
            q.append(u)
        else:
            go[0][c] = 0
    while q:
        v = q.popleft()
        if term[fail[v]]:
            term[v] = True
        fv = fail[v]
        for c in range(K):
            u = adj[v][c]
            if u != -1:
                fail[u] = go[fv][c]
                go[v][c] = u
                q.append(u)
            else:
                go[v][c] = go[fv][c]

    good = [s for s in range(m) if not term[s]]
    if 0 not in good:
        return 0
    idx = {s: i for i, s in enumerate(good)}
    g = len(good)
    M = [[0] * g for _ in range(g)]
    for s in good:
        i = idx[s]
        row = M[i]
        for c in range(K):
            t = go[s][c]
            j = idx.get(t)
            if j is not None:
                row[j] += 1

    def mul(A, B):
        C = [[0] * g for _ in range(g)]
        for i in range(g):
            Ai = A[i]
            Ci = C[i]
            for k in range(g):
                aik = Ai[k]
                if aik:
                    Bk = B[k]
                    for j in range(g):
                        bkj = Bk[j]
                        if bkj:
                            Ci[j] = (Ci[j] + aik * bkj) % MOD
        return C

    R = [[1 if i == j else 0 for j in range(g)] for i in range(g)]
    base = M
    e = n
    while e:
        if e & 1:
            R = mul(R, base)
        base = mul(base, base)
        e >>= 1
    return sum(R[idx[0]]) % MOD
